            measuredInputTokens: number;
            /** Measuredoutputtokens */
            measuredOutputTokens: number;
            /** Measuredtotaltokens */
            measuredTotalTokens: number;
            measurementFreshness: components["schemas"]["agent_MeasurementFreshness"];
